    export const getVoiceListCallsUrl = (centerId: string,
    params?: VoiceListCallsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/centers/${centerId}/voice-receptionist/calls?${stringifiedParams}` : `/v1/centers/${centerId}/voice-receptionist/calls`
}

