/**
 * @summary Da de alta el add-on de un centro: asigna su número puente y crea su suscripción con los minutos de su plan. Con `shouldBillWithStripe` añade además el add-on como líneas de la suscripción de Stripe del centro (409 VOICE_ADDON_BILLING_NOT_READY si el centro no tiene suscripción o falta `billing:setup`). No lo activa: lo activa el centro.
 */
export const platformProvisionVoiceReceptionist = async (centerId: string,
    provisionVoiceRequestDto: ProvisionVoiceRequestDto, options?: Parameters<typeof apiMutator>[1]): Promise<void> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiMutator<void>(getPlatformProvisionVoiceReceptionistUrl(centerId),
  {
    ...options,
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(provisionVoiceRequestDto)
  }
);}





